from pathlib import Path
import html,json,re,difflib
from bs4 import BeautifulSoup
R=Path(r'C:\Users\lokes\OneDrive\Documents\ChatGPT\restfulapi\http-status-style')
M={}
def p(x):return '<!-- wp:paragraph -->\n<p>'+x+'</p>\n<!-- /wp:paragraph -->'
def h(x):return '<!-- wp:heading -->\n<h2 class="wp-block-heading">'+x+'</h2>\n<!-- /wp:heading -->'
def c(x,l='http'):return '<!-- wp:code -->\n<pre class="wp-block-code"><code class="language-'+l+'">'+html.escape(x)+'</code></pre>\n<!-- /wp:code -->'
def t(head,rows):return '<!-- wp:table -->\n<figure class="wp-block-table"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></figure>\n<!-- /wp:table -->'
def refs(xs):return '<!-- wp:list -->\n<ul class="wp-block-list">'+''.join('<li><a href="'+u+'" target="_blank" rel="noopener">'+n+'</a></li>' for n,u in xs)+'</ul>\n<!-- /wp:list -->'
def save(id,blocks,title,desc,excerpt,key):
 raw='\n\n'.join(blocks+[p('Happy Learning !!')])+'\n'
 assert 'PLANNING NOTE' not in raw
 (R/'articles'/f'{id}.wp.html').write_text(raw,encoding='utf-8')
 M[id]=dict(seo_title=title,description=desc,excerpt=excerpt,keyphrase=key)

save('3070',[
p('<strong>HTTP 413 Content Too Large means that a server or proxy rejected a request because its body exceeds an allowed size.</strong> Reduce the body, or raise the limit at the component that rejected it. Increasing an application limit does not help when a reverse proxy rejects the upload first.'),
p('This often happens with file uploads, large JSON documents and batches containing many records. First find where the request stopped: the public gateway, the web server or the application parser.'),
h('1. When to Send HTTP 413'),p('Use 413 when the request content is larger than the endpoint is willing or able to process. For example, a document endpoint may accept files up to 10 MiB, while a settings endpoint allows only 64 KiB. Document each limit beside the request format.'),
p('The current name is Content Too Large. Older software may display Payload Too Large or Request Entity Too Large. The number 413 identifies the error even when the reason phrase differs, as the <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/413">MDN reference</a> explains.'),
c('HTTP/1.1 413 Content Too Large\nContent-Type: application/problem+json\n\n{\n  "type": "about:blank",\n  "title": "Content Too Large",\n  "status": 413,\n  "detail": "The upload exceeds the 10485760-byte limit.",\n  "max_bytes": 10485760\n}'),
p('Here, <em>max_bytes</em> is an application-defined extension, not a standard HTTP field. Describe the relevant limit without returning uploaded content. The HTTP status must communicate failure; returning HTTP 200 with an error number only in the body hides it from ordinary HTTP clients.'),
h('2. Distinguishing 413 from Other Request Errors'),p('The rejected part of the request determines the fix. A body-size increase will not repair a long URL or an unsupported file format.'),
t(['Status','Rejected part','Typical change'],[['413','Body','Send fewer records or a smaller file'],['414','Request target, including the query','Shorten the URL'],['431','Headers','Reduce cookies, tokens or custom fields'],['415','Content format','Use a supported media type and encoding']]),
h('3. Find the Rejecting Layer'),p('Start with a small upload that succeeds, then increase its size while keeping the URL, credentials and content type unchanged. Record the response headers and request identifier. Check gateway and application logs for that request. A proxy error page and an absent application log entry suggest that the request never reached the handler.'),
p('Measure bytes rather than characters. JSON can contain multibyte text, and multipart uploads include boundaries and field headers in addition to file data. A per-file limit and a total-request limit therefore need not match.'),
h('4. Configure a Deliberate Limit'),p('In nginx, <em>client_max_body_size</em> controls accepted request-body size. Apply the policy to the upload location rather than expanding every endpoint. This fragment belongs in an existing server block:'),
c('location /uploads/ {\n    client_max_body_size 12m;\n    proxy_pass http://127.0.0.1:3000;\n}','nginx'),
p('For an Express JSON endpoint, register the JSON parser before the route. This setting controls JSON parsing, not multipart file-upload middleware:'),c("app.use(express.json({ limit: '1mb' }));",'javascript'),
p('For Spring Boot servlet multipart uploads, configure both per-file and total-request limits. Leave room for form fields and multipart overhead:'),c('spring.servlet.multipart.max-file-size=10MB\nspring.servlet.multipart.max-request-size=12MB','properties'),
p('These are configuration examples, not universal recommended values. Check storage, concurrency and processing cost before raising limits. Keep proxy and application policies consistent. A larger proxy allowance can leave room for overhead, while the application enforces the actual file policy.'),
h('5. Should the Client Retry?'),p('Sending the same oversized body repeatedly normally fails again. For a temporary restriction, the server can supply <em>Retry-After</em>. Otherwise change the request: reduce the batch, shrink the file, or use the API\'s documented resumable-upload workflow. Splitting bytes arbitrarily does not work unless the server supports reassembly.'),
p('Streaming the request can reduce client memory use, but does not exempt it from server limits. If a request includes compressed content, also check the parser\'s policy for decompressed size. A smaller transfer can still expand into more content than the application accepts.'),
h('6. Test the Boundary'),p('Send files just below and above the documented limit. For an existing multipart endpoint, this command uploads a file without placing its bytes in a shell argument:'),c('curl -i -F "file=@sample.pdf" https://api.example.com/uploads/','bash'),
p('Replace the URL with a test endpoint. Confirm that the accepted upload reaches the handler and the oversized one returns 413. Repeat through the deployed proxy, not only the application port. Test multiple files and additional form fields when the API supports them.'),
h('7. Conclusion'),p('Fix 413 by changing the request size or the correct server-side limit. Find the rejecting component first, then test both sides of the intended boundary.'),h('8. References'),refs([('MDN: 413','https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/413'),('nginx body limit','https://nginx.org/en/docs/http/ngx_http_core_module.html#client_max_body_size'),('Express body-parser','https://expressjs.com/en/resources/middleware/body-parser/'),('Spring Boot multipart uploads','https://docs.spring.io/spring-boot/how-to/spring-mvc.html')])],
'HTTP 413 Content Too Large: Causes, Limits and Fixes','Fix HTTP 413 by finding the rejecting proxy or application, checking upload limits, and reducing the body or configuring nginx, Express and Spring Boot.','HTTP 413 means the request body exceeds a server limit. Find the rejecting layer, configure upload limits, and learn when reducing or retrying the request helps.','http 413')

save('3009',[
p('<strong>HTTP 415 Unsupported Media Type means that an endpoint cannot process the format of the request body.</strong> Check the body, its <em>Content-Type</em> and any <em>Content-Encoding</em>. Changing only <em>Accept</em> does not fix an unsupported input format.'),
p('An orders endpoint that accepts JSON may reject form data or XML. The same URL can support different formats for different methods, so inspect the contract for the operation being called.'),
h('1. What Causes HTTP 415?'),p('A media type describes a format, such as <em>application/json</em>. A content encoding describes a transformation, such as gzip compression. A server can understand JSON but reject compressed JSON when the operation does not support that encoding.'),
p('A missing content type can also cause 415 when the endpoint requires one. The server may detect an unsupported format from the content itself. See <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/415">MDN\'s 415 reference</a> for these cases.'),
h('2. Content-Type Is Different from Accept'),p('The request\'s <em>Content-Type</em> describes what you sent. Its <em>Accept</em> header describes the response formats you can receive. An API can accept JSON input while returning a different output format.'),
t(['Status','Problem','Inspect'],[['415','Unsupported request representation','Content-Type, Content-Encoding and body'],['406','No acceptable response under the server\'s negotiation policy','Accept and response types'],['400','Malformed request, such as invalid JSON','Parsing error and syntax'],['422','Supported content that cannot be processed semantically','Validation rules and values']]),
p('Framework error mappings vary. Read the error body and server logs before inferring which stage failed. Document the mapping consistently so that clients can distinguish format, syntax and validation problems.'),
h('3. Fix curl and Postman Requests'),p('For an endpoint expecting JSON, send JSON bytes and the matching content type. This request assumes an order object with a <em>sku</em> and a <em>quantity</em>:'),c('curl -i https://api.example.com/orders \\\n  -H "Content-Type: application/json" \\\n  -H "Accept: application/json" \\\n  --data \'{"sku":"BOOK-7","quantity":2}\'','bash'),
p('In Postman, choose Body, raw, then JSON, and inspect the outgoing headers. A stale manually entered header can disagree with the body editor. For SDK-generated requests, inspect the actual request rather than assuming that an object was serialized correctly.'),
p('Do not relabel XML or form data as JSON to get past the format check. Convert the body or deliberately add support on the server. A matching label alone cannot make the bytes parse correctly.'),
h('4. Send JSON or FormData with fetch'),p('For JSON, serialize the object and set the content type. Check <em>response.ok</em>: an HTTP error response does not by itself reject the fetch promise.'),c("const response = await fetch('/orders', {\n  method: 'POST',\n  headers: { 'Content-Type': 'application/json' },\n  body: JSON.stringify({ sku: 'BOOK-7', quantity: 2 })\n});\nif (!response.ok) {\n  throw new Error(`Request failed: ${response.status}`);\n}",'javascript'),
p('For browser <em>FormData</em>, let the browser generate <em>Content-Type</em>. It includes the boundary separating the form parts. Manually setting <em>multipart/form-data</em> without the matching boundary can make the upload unparseable.'),
h('5. Check the Server Mapping'),p('In Spring MVC, a mapping declared with <em>consumes = "application/json"</em> intentionally restricts input to JSON. Check the mapping and installed message converters, which translate request bytes into application objects. Changing <em>produces</em>, the response-format setting, does not add input-format support.'),
p('In Express, JSON middleware must run before the route. Depending on middleware and application checks, an unsupported content type may leave the body unparsed rather than automatically return 415. Make the endpoint\'s behavior explicit instead of accepting an absent parsed body as an empty order.'),
h('6. Return an Actionable Error'),p('Explain what the operation accepts without echoing confidential input. The error response\'s own content type describes the error body, not the rejected request:'),c('HTTP/1.1 415 Unsupported Media Type\nContent-Type: application/problem+json\nAccept-Post: application/json\n\n{\n  "type": "about:blank",\n  "title": "Unsupported Media Type",\n  "status": 415,\n  "detail": "This operation accepts application/json."\n}'),
p('Where supported, <em>Accept-Post</em> advertises POST input formats and <em>Accept-Patch</em> advertises patch-document formats. For an unsupported content encoding, RFC 9110 describes an <em>Accept-Encoding</em> response field. Also document the requirements before clients encounter the error.'),
h('7. Test the Fix'),p('Compare a supported format, an unsupported format and malformed content in a supported format. Keep the URL and authentication unchanged. Verify that valid JSON reaches the handler, XML follows the documented 415 policy, and malformed JSON follows the parsing-error policy. Retrying unchanged bytes and headers will not resolve a format mismatch.'),
h('8. Conclusion'),p('A 415 concerns the incoming representation. Make the body, content type, encoding and endpoint contract agree, then check parsing and validation separately.'),h('9. References'),refs([('MDN: 415','https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/415'),('RFC 9110: 415','https://www.rfc-editor.org/rfc/rfc9110.html#section-15.5.16'),('Express body-parser','https://expressjs.com/en/resources/middleware/body-parser/'),('Spring MVC request mapping','https://docs.spring.io/spring-framework/reference/web/webmvc/mvc-controller/ann-requestmapping.html')])],
'HTTP 415 Unsupported Media Type: Causes and Fixes','Fix HTTP 415 by matching Content-Type, Content-Encoding and the body to the endpoint. Includes curl, Postman, fetch and server-side checks.','HTTP 415 rejects an unsupported request format. Fix JSON and multipart requests, distinguish 415 from 406 and 400, and return useful errors.','415 unsupported media type')
save('3004',[
p('<strong>HTTP 431 Request Header Fields Too Large means that one request header, or the combined headers, exceeds a server limit.</strong> Reduce the headers before resending. Large cookies, long bearer tokens and repeated custom fields are useful places to start.'),p('A proxy or HTTP server can reject headers before application code runs. If the route has no matching log entry, inspect the components in front of it rather than changing the JSON-body parser.'),
h('1. When to Return HTTP 431'),p('<a href="https://www.rfc-editor.org/rfc/rfc6585.html#section-5">RFC 6585</a> defines 431 for oversized request headers, whether one field or the total set is too large. If one field is responsible, identify its name when practical. Caches must not store 431 responses.'),c('HTTP/1.1 431 Request Header Fields Too Large\nContent-Type: application/problem+json\nCache-Control: no-store\n\n{\n  "type": "about:blank",\n  "title": "Request Header Fields Too Large",\n  "status": 431,\n  "detail": "Reduce the Cookie header before resending."\n}'),p('Name the field without returning its value. Logs should record names and measured lengths, not complete session cookies or authorization tokens.'),
h('2. Why Headers Become Too Large'),p('Browsers send cookies whose domain and path match the URL. Applications sharing a parent domain can accumulate cookies on requests to the same service. Clearing that site\'s cookies can help confirm the cause, but may sign the user out. Reduce stored cookie data and use suitable scope for the lasting fix.'),p('A JSON Web Token, or JWT, carries signed claims in a compact string. Long permission lists and profile data increase the Authorization field on every call. Keep claims small and use server-side lookup for data that need not travel with each request.'),p('Also inspect tracing baggage, repeated custom fields and headers added by proxies. Compare each hop: a request within the client-facing limit can grow as intermediaries add metadata.'),
h('3. 431 vs 413, 414 and 400'),p('The oversized part determines the fix. The implementation may report a less specific status, so read its logs too.'),t(['Code','Problem','First check'],[['431','Headers too large','Cookies, tokens and added metadata'],['413','Body too large','Upload or JSON limit'],['414','Request target too long','Path and query'],['400','General request parsing failure','Parser error and server logs']]),p('nginx documents 400 when an individual request-header field exceeds a large-header buffer, and 414 when the request line exceeds one buffer. The same header-size problem can therefore appear as 400 at nginx and 431 at Node.js.'),
h('4. Check Server and Proxy Limits'),p('Node.js accepts a maxHeaderSize option when creating an HTTP server. Its default header-overflow handling attempts to return 431. This server explicitly allows 16 KiB of headers:'),c("import http from 'node:http';\n\nhttp.createServer({ maxHeaderSize: 16 * 1024 }, (req, res) => {\n  res.end('OK');\n}).listen(3000, '127.0.0.1');",'javascript'),p('Save it as server.mjs and run <em>node server.mjs</em>. The handler runs only after parsing succeeds. A route error handler cannot repair a request rejected before that point.'),p('For nginx, inspect client_header_buffer_size and large_client_header_buffers. An individual field must fit in one large buffer; extra buffers do not combine into a larger single-field allowance. For Spring Boot, check server.max-http-request-header-size and how the embedded server applies it.'),p('Increase limits only after measuring legitimate traffic. A broad increase can hide a cookie or token design problem and allow more memory use per request. A lower fixed limit at an outer load balancer still applies.'),
h('5. How Clients Should Recover'),p('Retry after reducing the offending fields. Compare a browser request with a clean session, or remove unnecessary custom metadata in an API client. Preserve credentials required by the service. Do not move secrets into a URL: URLs can appear in history and access logs.'),
h('6. Test the Header Boundary'),p('Against the local Node.js server, this standard-library Python client compares a small header with one above the configured limit:'),c("import http.client\n\nfor size in (100, 20000):\n    conn = http.client.HTTPConnection('127.0.0.1', 3000)\n    conn.request('GET', '/', headers={'X-Demo': 'x' * size})\n    response = conn.getresponse()\n    print(size, response.status)\n    response.read()\n    conn.close()",'python'),p('The small request should return 200 and the large one 431 on this server. Repeat through the deployed proxy, where status and limits can differ. Use generated test values rather than real tokens.'),
h('7. Conclusion'),p('Find which field grew and which component rejected it. Reduce unnecessary metadata first, then align deliberate limits across the request path.'),h('8. References'),refs([('RFC 6585: 431','https://www.rfc-editor.org/rfc/rfc6585.html#section-5'),('Node.js HTTP','https://nodejs.org/api/http.html'),('nginx header buffers','https://nginx.org/en/docs/http/ngx_http_core_module.html#large_client_header_buffers'),('Spring Boot properties','https://docs.spring.io/spring-boot/appendix/application-properties/index.html')])],
'HTTP 431: Request Header Fields Too Large, Causes and Fixes','Fix HTTP 431 by reducing cookies, tokens and request headers. Learn how Node.js, nginx and Spring Boot limits differ and test the size boundary.','HTTP 431 means request headers are too large. Find oversized cookies or tokens, check proxy and server limits, and retry after reducing the fields.','http 431')

save('2994',[
p('<strong>HTTP 410 Gone means that a resource is no longer available and the server expects that condition to be permanent.</strong> Use it when the API knows the resource was deliberately removed. Use 404 when its removal history or permanence is unknown.'),p('A retired report, an expired download that will not be renewed, or a withdrawn API version can fit this meaning. A temporary outage does not. The distinction helps clients stop repeating requests that cannot succeed.'),
h('1. When to Send HTTP 410'),p('Suppose an API keeps generated reports for seven days. After expiry, it retains a small record that a report existed but its download was removed permanently. The endpoint can return 410 with instructions for creating a fresh report.'),c('HTTP/1.1 410 Gone\nContent-Type: application/problem+json\nCache-Control: no-store\n\n{\n  "type": "about:blank",\n  "title": "Gone",\n  "status": 410,\n  "detail": "This report download expired. Create a new report."\n}'),p('A new report is a new operation and may contain different data. This response does not promise restoration of the old bytes. The explicit no-store policy suits this example of a private download error.'),
h('2. HTTP 404 vs 410'),p('Both statuses describe an unavailable resource. The difference is what the server knows, as explained in the <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/410">410 reference</a>.'),t(['Situation','Suitable response','Reason'],[['Unknown identifier or uncertain removal history','404 Not Found','No assertion of permanent removal'],['Known resource removed for good','410 Gone','Permanent absence is known'],['Resource moved to an equivalent URL','An appropriate redirect, such as 308','The client can use the new location'],['Temporary outage','503 Service Unavailable','The service may recover']]),p('An API does not have to retain deletion history forever. Keeping a tombstone, a small record of a removed identifier, has storage and privacy costs. Once the API no longer knows that history, it can use 404. Document the policy clients should rely on.'),
h('3. When Not to Return 410'),p('Do not use 410 for maintenance, overload, or a resource merely hidden by permissions. Revealing that a private identifier once existed can leak information. Apply authorization and resource-disclosure policy before returning removal details.'),p('A successful DELETE and a later GET are different requests. The deletion can return success while the later retrieval reports absence. Repeated DELETE behavior follows method semantics and the API\'s policy; 410 is not a universal replacement for every deletion response.'),
h('4. Retiring an API Version'),p('Announce retirement while the old API still works. Supply a migration guide, a cutoff date and a way to find consumers still calling it. RFC 8594 defines the Sunset header for an expected unavailability date, but a header does not migrate clients or make incompatible changes safe.'),p('After the cutoff, a dedicated retired-version handler can return 410. Name the version and link to migration instructions. Avoid blindly redirecting writes to a version with different request schemas or behavior.'),c('HTTP/1.1 410 Gone\nContent-Type: application/problem+json\nCache-Control: max-age=300\n\n{\n  "type": "about:blank",\n  "title": "API version retired",\n  "status": 410,\n  "detail": "Version 1 is no longer served. Migrate to version 2.",\n  "migration": "https://api.example.com/docs/migrate-v2"\n}'),p('Here, migration is an application-defined field. The short cache lifetime suits a public version-retirement message. Do not copy it onto personalized errors without reviewing whether sharing is safe.'),
h('5. Clients, Caches and Search Engines'),p('Stop unchanged retries and show the removal message. Invoke a replacement or migration workflow deliberately: a resource disappearing does not authorize a client to create another purchase or subscription automatically.'),p('410 is heuristically cacheable, meaning caches may reuse it under HTTP rules without an explicit freshness lifetime. Choose Cache-Control deliberately, especially if a URL might be restored. Correcting an accidental 410 at the origin may not remove cached copies immediately.'),p('For public pages, replace broken internal links and update navigation. Google treats 404 and 410 as removal signals. Do not promise a ranking improvement or guaranteed removal time from choosing one code. Return the status that accurately describes the resource.'),
h('6. Test the Removal Policy'),p('Check a known removed identifier, an identifier that never existed, an active identifier and an unauthorized request. Confirm that the responses follow the policy without exposing private history.'),c('curl -i https://api.example.com/reports/expired-report/download','bash'),p('Use a test URL you control. Verify a real HTTP 410, rather than HTTP 200 with an error message in the body. Also test cache behavior and how the consuming SDK or app reacts.'),
h('7. Conclusion'),p('Use 410 for a resource known to be permanently gone when that fact is safe to disclose. Explain the next action, avoid unchanged retries and choose a deliberate cache policy.'),h('8. References'),refs([('MDN: 410','https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/410'),('RFC 9110: 410','https://www.rfc-editor.org/rfc/rfc9110.html#section-15.5.11'),('RFC 8594: Sunset','https://www.rfc-editor.org/rfc/rfc8594.html'),('Google: HTTP status codes','https://developers.google.com/crawling/docs/troubleshooting/http-status-codes')])],
'HTTP 410 Gone: When to Use It Instead of 404','Learn when HTTP 410 fits removed resources and retired API versions, how it differs from 404, and how clients and caches should handle it.','Use HTTP 410 for a resource known to be permanently removed. Compare it with 404, plan API retirement, control caching, and test the removal policy.','http 410 gone')
save('2982',[
p('<strong>A timeout has no universal HTTP status: 408 concerns receiving a request, while 504 concerns a gateway waiting for an upstream response.</strong> nginx may log 499 when its client disconnects, and Cloudflare uses 524 for an origin timeout after connecting. A client can also time out without receiving any HTTP response.'),p('Identify which component stopped waiting. The browser, proxy, application and database may have separate deadlines. A status in one component\'s log need not be a response seen by the caller.'),
h('1. Which Code Means Which Timeout?'),p('Read the signal together with its producer and the request path. This separates standard responses from implementation-specific observations.'),t(['Signal','Producer','Meaning'],[['408','Server receiving a request','The request was not received completely within its waiting period'],['504','Gateway or proxy','An upstream response did not arrive in time'],['499','nginx log or compatible service','Its client disconnected before the response completed'],['524','Cloudflare','An origin read or write timed out after connection'],['Client exception or curl exit 28','Calling program','Its local deadline expired; a response may be absent']]),
p('For 408, inspect request arrival and upload timing. For 504, inspect the upstream call. For 499, ask which program was the client of the component that logged it. Behind another proxy, that client may be a gateway rather than the end user.'),
h('2. HTTP 408 Concerns Receiving a Request'),p('A server can return 408 after waiting too long for the complete request. That differs from accepting the request and then taking too long to generate a report. Slow uploads, interrupted clients and idle connections can put the failure on the receiving side.'),p('Some servers close the connection without a response; others issue 408 on idle connections. Inspect server logs before deciding an application handler timed out. The <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/408">408 documentation</a> explains that connection-level context.'),
h('3. HTTP 504 Concerns an Upstream Response'),p('A gateway can accept a complete request, forward it to an application, and time out waiting for the result. It can return 504 even if the application later finishes. A slow dependency, saturated worker pool or stalled database query may be the cause.'),p('Compare <a href="https://restfulapi.net/http-status-502-bad-gateway/">502 Bad Gateway</a>, where an upstream response was invalid, and <a href="https://restfulapi.net/http-status-503-service-unavailable/">503 Service Unavailable</a>, commonly used for temporary inability to serve requests. These are related failures, but describe different events.'),
h('4. Why 499 and 524 Appear'),p('<a href="https://developers.cloudflare.com/support/troubleshooting/http-status-codes/4xx-client-error/error-499/">499</a> is nginx\'s nonstandard signal for a client that closed the connection. A cancelled browser request or shorter calling-client timeout can cause it. It does not mean nginx successfully sent a 499 response to a disconnected client.'),p('<a href="https://developers.cloudflare.com/support/troubleshooting/http-status-codes/cloudflare-5xx-errors/error-524/">Cloudflare 524</a> concerns an origin read or write timeout after connection. Cloudflare 522 concerns the connection stage. Check current limits for your product rather than copying one timeout value from another deployment.'),
h('5. Allocate a Timeout Budget'),p('A timeout budget is the maximum duration of the whole operation. Allocate time to dependencies and leave room for the application to report failure. Stopping a dependency call before the proxy deadline gives the application a chance to return an actionable response.'),p('For example, the dependency might get 3 seconds, the gateway 5 seconds and the client 7 seconds. These are illustrative values. Include queueing, connection setup, retries and transfer time in a real budget. An idle-read timeout differs from a total deadline: occasional bytes can reset the former without bounding total duration.'),p('Propagate cancellation when supported, but do not assume disconnecting the client stopped database work. For operations normally taking minutes, return a job handle and expose progress through a status endpoint instead of holding one request open indefinitely.'),
h('6. Is a Retry Safe?'),p('A timeout establishes that the caller lacks a timely result, not that a write failed. Before repeating an order, charge or deployment, inspect operation status or reuse the same idempotency key under the API\'s contract. A new key can create another operation.'),p('For transient failures on safely retryable calls, use bounded retries with increasing delays and a random spread between clients. Count SDK retries in the same budget. Retries at several layers can multiply load during an outage.'),
h('7. Diagnose a Timed Request'),p('curl separates connection and total deadlines. Run this against a test endpoint and correlate the result with gateway and application logs:'),c('curl -i --connect-timeout 2 --max-time 5 https://api.example.com/reports/summary','bash'),p('A local curl timeout normally exits with code 28; curl does not generate an HTTP 408 from that local deadline. Record the actual response status, elapsed time and correlation identifier. Remove credentials before sharing output. Compare a fast request with the slow operation to distinguish reachability from processing duration.'),
h('8. Conclusion'),p('Find who stopped waiting before increasing timeouts. Track request receipt, upstream processing and cancellation separately, and verify write outcomes before retrying.'),h('9. References'),refs([('MDN: 408','https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/408'),('RFC 9110: 504','https://www.rfc-editor.org/rfc/rfc9110.html#section-15.6.5'),('Cloudflare: 499','https://developers.cloudflare.com/support/troubleshooting/http-status-codes/4xx-client-error/error-499/'),('Cloudflare: 524','https://developers.cloudflare.com/support/troubleshooting/http-status-codes/cloudflare-5xx-errors/error-524/'),('curl manual','https://curl.se/docs/manpage.html')])],
'HTTP Timeout Codes: 408 vs 504 vs 499 vs 524','Compare HTTP 408, 504, nginx 499 and Cloudflare 524. Find who timed out, allocate request budgets, and retry writes without duplicating operations.','Identify who timed out: the request receiver, gateway, CDN or client. Compare 408, 504, 499 and 524, configure deadlines, and handle retries safely.','timeout status code')

save('2978',[
p('Some status numbers come from a particular proxy or API provider rather than the HTTP standard. Others, such as browser status 0, are not HTTP responses at all. Identify the component that produced the signal before choosing a fix.'),p('This reference covers nginx 499, Cloudflare 520-527, provider-specific 529 and browser status 0. Treat the provider and number as a pair: the same number need not have the same meaning in another product.'),
h('1. Standard and Provider-Specific Codes'),p('The <a href="https://www.iana.org/assignments/http-status-codes/http-status-codes.xhtml">IANA registry</a> lists registered HTTP status codes. A product can still expose an unregistered value in a response or log, but that does not make the value portable across API clients and gateways.'),p('Preserve unfamiliar numbers in diagnostics alongside the responding service and request identifier. A missing client-library constant does not make the status meaningless. Equally, a provider-specific code is not enough to justify a universal retry rule.'),
h('2. nginx 499: Client Closed Request'),p('<a href="https://developers.cloudflare.com/support/troubleshooting/http-status-codes/4xx-client-error/error-499/">499</a> records a client disconnect before the server could finish responding. It often appears in nginx logs when the caller cancels or reaches its deadline. The caller may receive no HTTP response at all.'),p('Identify the client relative to that server: it may be another proxy. Compare request duration, the proxy\'s timeout and application completion time. Occasional cancellations can be normal. A rise concentrated on one slow endpoint deserves latency investigation.'),
h('3. Cloudflare 520-526: Investigate the Origin Path'),p('Cloudflare sits between a caller and the origin, the server hosting the application. Its codes distinguish failures along that path. Correlate the request time and Ray ID with origin logs.'),t(['Code','Meaning in Cloudflare','First investigation'],[['520','Unexpected origin response','Crashes, empty or malformed responses'],['521','Web server down or refusing connection','Listener and firewall'],['522','Connection timeout','Reachability and connection handling'],['523','Origin unreachable','Origin address and routing'],['524','Read or write timeout after origin connection','Slow processing or stalled transfer'],['525','SSL handshake failure','Origin TLS negotiation'],['526','Invalid SSL certificate under the relevant validation mode','Validity, hostname and trust chain']]),p('TLS encrypts a connection and authenticates the server. A handshake or certificate error therefore needs different checks from a slow database query. Correct the certificate or TLS configuration instead of routinely disabling validation.'),p('The table is a starting point, not an exhaustive cause list. Follow <a href="https://developers.cloudflare.com/support/troubleshooting/http-status-codes/cloudflare-5xx-errors/">Cloudflare\'s current error documentation</a>. A test against localhost cannot verify the CDN-to-origin network or TLS path.'),
h('4. What About 527?'),p('Older lists associate 527 with Railgun, a legacy Cloudflare origin-connection feature. Do not treat it as a current generic timeout code. If it appears in an old log or monitoring label, establish the product and date before applying that interpretation.'),p('The current Cloudflare 5xx overview does not give 527 a general HTTP meaning. Keep historical mappings separate from active alerts. When evidence is incomplete, preserve the response and ask the provider rather than inventing a cause from the number.'),
h('5. HTTP 529: Check the Provider Contract'),p('The <a href="https://platform.claude.com/docs/en/api/errors">Claude API</a> uses 529 with the error type <em>overloaded_error</em> for temporary overload. This is provider-specific, not a meaning every service must follow. Compare it with <a href="https://restfulapi.net/http-status-429-too-many-requests/">429</a> under the service\'s rate-limit or quota policy and <a href="https://restfulapi.net/http-status-503-service-unavailable/">503</a> for standard service unavailability.'),p('For safely retryable transient failures, use bounded delays and check whether the SDK already retries. Keep partial streamed output separate from a completed result. After a stream starts with HTTP 200, a later error can arrive inside the stream rather than as a new HTTP status.'),
h('6. Status 0 in Browsers'),p('Status 0 is not an HTTP response status. Fetch Response objects of type <em>opaque</em>, <em>opaqueredirect</em> or <em>error</em> expose 0. Network and CORS failures can instead reject the fetch promise, leaving no response object for application code to inspect.'),p('An opaque response intentionally hides its details, as with certain cross-origin requests using no-cors mode. Switching to that mode does not grant JavaScript access to JSON. Check the console and network panel for DNS, TLS, cancellation and CORS evidence.'),p('CORS, or Cross-Origin Resource Sharing, controls whether browser JavaScript may read a response from another origin. A server may process a request even when browser policy prevents the app reading the result. Missing visibility is not proof that a write did nothing.'),
h('7. What Should Your API Return?'),p('Prefer a registered status whose meaning fits the failure, and put application detail in a documented error body. Use 503 for temporary service unavailability or 504 when acting as a gateway that timed out on an upstream response. Do not send 499 merely to describe slow application work.'),p('Test clients with unfamiliar statuses too. They should preserve diagnostics and fail clearly, without assuming an empty body means success or automatically repeating writes. The <a href="https://restfulapi.net/http-status-codes/">HTTP status overview</a> covers standard choices.'),
h('8. Conclusion'),p('Read unofficial codes in their producer\'s context. Separate logged disconnects, provider responses and browser-local failures before selecting a fix or retry policy.'),h('9. References'),refs([('IANA registry','https://www.iana.org/assignments/http-status-codes/http-status-codes.xhtml'),('Cloudflare 5xx','https://developers.cloudflare.com/support/troubleshooting/http-status-codes/cloudflare-5xx-errors/'),('Cloudflare 499','https://developers.cloudflare.com/support/troubleshooting/http-status-codes/4xx-client-error/error-499/'),('Claude errors','https://platform.claude.com/docs/en/api/errors'),('MDN: Response.status','https://developer.mozilla.org/en-US/docs/Web/API/Response/status')])],
'Unofficial HTTP Status Codes: 499, 520-527, 529 and 0','Understand nginx 499, Cloudflare 520-527, Claude 529 and browser status 0. Identify who produced the code before choosing a fix or retry policy.','A reference to provider-specific codes and browser status 0: what 499, Cloudflare 52x and 529 mean, where to investigate, and when to retry.','unofficial http status codes')

raw=(R/'originals/2981.wp.html').read_text(encoding='utf-8')
replacements={
'In short, we send HTTP 402':'We send HTTP 402',
'APIs still send HTTP 402 today to say that a request failed because a payment is missing, such as an empty prepaid balance or a declined card, and the x402 protocol uses HTTP 402 to ask the client for a payment inside the same HTTP exchange.':'APIs use HTTP 402 for payment-related failures, such as an empty prepaid balance or a declined card. The x402 protocol uses it to request payment during an HTTP exchange.',
'with two extension members for the balance and the top-up link.':'with extension members for the balance, cost and top-up link.',
'The common convention is a request that is valid and authorized but cannot run until a payment happens, and the response tells the client how to pay.':'A common convention is to use it for a valid, authorized request that cannot run until payment. The response explains how the client can pay.',
'A lapsed subscription and a missing feature look similar but need different codes.':'A lapsed subscription and a feature excluded from a plan can look similar, but the corrective action differs.',
'The x402 protocol targets payments that a checkout page handles badly.':'The x402 protocol supports payment flows that do not fit an interactive checkout page.',
'cannot fill in a card form or create an account, so the agent pays':'may have no interactive checkout available, so it can pay',
'A signed payment is money, so the server must not accept the same authorization twice.':'A signed authorization can authorize a transfer of funds, so the payment system must prevent its reuse.',
'Clients stop and pay instead of retrying.':'Clients stop unchanged retries and follow the documented billing or payment flow.'}
for a,b in replacements.items():
 assert a in raw,a
 raw=raw.replace(a,b)
a=BeautifulSoup((R/'originals/2981.wp.html').read_text(encoding='utf-8'),'html.parser');b=BeautifulSoup(raw,'html.parser')
for s in ('pre','h2','h3','img','table'):
 assert [str(x) for x in a.select(s)]==[str(x) for x in b.select(s)],s
(R/'articles/2981.wp.html').write_text(raw,encoding='utf-8')
(R/'2981.diff').write_text(''.join(difflib.unified_diff((R/'originals/2981.wp.html').read_text(encoding='utf-8').splitlines(True),raw.splitlines(True))),encoding='utf-8')
M['2981']=dict(seo_title='HTTP 402 Payment Required: Meaning, Uses and x402',description='Learn when APIs use HTTP 402 Payment Required, how it differs from 401, 403 and 429, and how x402 payment headers work, with a simulated Python example.',excerpt='HTTP 402 is reserved by HTTP but used by APIs for payment-related failures. Learn how clients should respond and how x402 adds payment negotiation to HTTP.',keyphrase='http 402 payment required')
(R/'metadata.json').write_text(json.dumps(M,indent=2),encoding='utf-8')
for id in M:
 s=BeautifulSoup((R/'articles'/f'{id}.wp.html').read_text(encoding='utf-8'),'html.parser')
